"""Explicit provisional editorial consolidation, separate from raw annotations.

Listed groups are decisions by the primary assistant after seeing all answers.
Unlisted candidates merge only on identical name AND description strings.
"""
from collections import defaultdict
from fipi_eda50 import RUN, read, write, digest

# canonical ID, allowed literal names, operation/boundary definition.
GROUPS=[
 ('linear_equation',['Решать линейное уравнение с числовыми коэффициентами'],'Преобразовать аффинное равенство одной переменной с числовыми коэффициентами в множество решений. Построение модели, снятие степени/логарифма и неравенства не входят.'),
 ('pythagoras',['Находить длину по теореме Пифагора','Применять теорему Пифагора к прямоугольному треугольнику'],'Связать квадраты катетов и гипотенузы после установления прямого угла; при восстановлении длины выбрать положительный корень. Простая сумма квадратов без прямоугольного треугольника не подтверждает это действие.'),
 ('quadratic_discriminant',['Находить корни квадратного уравнения через дискриминант'],'При ненулевом старшем коэффициенте вычислить дискриминант и получить действительные корни. Подсчёт положительных корней с параметром — отдельное действие.'),
 ('graph_coordinates',['Считывать координаты отмеченной точки с графика'],'По установленному масштабу координатной сетки считать отмеченные точки и явно заданные пересечения с осями. Произвольный эскиз без точной привязки не даёт точных координат; дальнейшее восстановление формулы отдельно.'),
 ('graph_intersection',['Сводить пересечение графиков к равенству значений'],'Для y=f(x),y=g(x) составить f(x)=g(x) на общей области. Решение полученного уравнения и чтение графика отдельно.'),
 ('direct_proportion',['Восстанавливать прямую пропорциональность по точке'],'Для y=kx по точке с ненулевой абсциссой вычислить k. Не приравнивать к восстановлению общего y=kx+b по двум точкам.'),
 ('classical_probability',['Вычислять вероятность по числу равновозможных исходов'],'В конечной равновозможной модели вычислить m/n. Обоснование равновозможности и комбинаторный подсчёт не включаются автоматически.'),
 ('equiprobable_model',['Строить равновозможную модель случайного выбора'],'Задать элементарные исходы случайного выбора и обосновать одинаковые вероятности. Сама формула m/n — отдельный узел.'),
 ('bernoulli_model',['Моделировать независимые испытания с двумя исходами'],'Задать последовательность испытаний с двумя исходами, постоянной вероятностью и независимостью. Эти предпосылки должны быть видны или явно приняты в модели.'),
 ('zero_product',['Решать уравнение через нулевое произведение'],'Получить нули множителей и объединить допустимые корни на общей области. Факторизация без решения не приравнивается ко всему действию; нуль не теряется делением.'),
 ('exponential_equation',['Сводить показательное уравнение к равенству показателей'],'Привести степени к общему положительному основанию, отличному от 1, и приравнять показатели. Решение последующего линейного уравнения отдельно.'),
 ('exponential_substitution',['Заменять показатели степенной переменной'],'Ввести t=b^x>0 при b>0,b≠1 и согласовать остальные степени с t. Обратный переход и решение неравенств отдельно.'),
 ('power_laws',['Преобразовывать степени положительного основания'],'Использовать законы степени степени, произведения и частного на допустимой области положительного основания. Не переносить безусловно на отрицательное основание.'),
 ('elementary_trig_equation',['Решать простейшее тригонометрическое уравнение'],'Решить sin x=c или cos x=c на указанной области; на всей прямой выписать полные периодические серии. Не считать решением только одно значение без учёта области.'),
 ('periodic_interval',['Отбирать периодические корни на заданном промежутке'],'Подставить периодические серии в границы и определить все целые параметры. Конечный набор без периодического параметра хранится отдельно.'),
 ('cosine_law',['Применять теорему косинусов'],'Связать три стороны и косинус угла между двумя сторонами невырожденного треугольника. Предпосылка — именно этот треугольник и соответствующие стороны.'),
 ('similarity_AA',['Доказывать подобие по двум углам'],'Установить две пары равных углов и зафиксировать соответствие вершин/сторон. Использование уже доказанного подобия не равно доказательству AA.'),
 ('similar_area',['Находить отношение площадей подобных фигур'],'Возвести коэффициент подобия соответствующих длин в квадрат. Нельзя брать произвольное отношение двух отрезков.'),
 ('right_triangle_area',['Находить площадь прямоугольного треугольника'],'После установления прямого угла вычислить половину произведения катетов. Распознавание прямого угла отдельно.'),
 ('diameter_angle',['Использовать прямой вписанный угол на диаметре'],'Для точки окружности вне концов диаметра установить прямой угол, опирающийся на диаметр.'),
 ('isosceles_angles',['Выражать углы равнобедренного треугольника'],'Из равенства сторон установить равенство противолежащих углов и при необходимости выразить угол при вершине.'),
 ('arithmetic_series',['Суммировать арифметическую прогрессию'],'По числу членов и крайним членам найти сумму арифметической прогрессии; отдельно учитывать заменённые члены. Доказательство минимальности набора отдельно.'),
 ('integer_construction',['Строить целочисленный пример с заданными ограничениями'],'Предъявить целые числа/объект и проверить все требуемые количество, различность, остатки/кратность и сумму. Пример доказывает существование, но не оптимальность без общей границы.'),
 ('finite_exhaustion',['Доказывать утверждение полным конечным перебором'],'Вывести конечный диапазон целочисленных случаев и рассмотреть каждый; произвольная числовая проба не является полным доказательством.'),
 ('derivative_monotonicity',['Устанавливать монотонность по знаку производной'],'Установить знак производной на промежутках и сделать вывод о монотонности исходной функции.'),
 ('stationary_point',['Находить стационарные точки по нулю производной'],'Решить f′=0 на допустимой области и отобрать точки исследуемого промежутка; вывод о типе экстремума отдельно.'),
 ('global_interval_extreme',['Находить глобальный экстремум на отрезке'],'По монотонности либо сравнению концов и критических точек установить глобальный экстремум и его значение. Не смешивать с вопросом об абсциссе локального экстремума.'),
 ('local_extreme_sign',['Определять локальный экстремум по смене знака производной'],'Установить смену +→- для максимума или -→+ для минимума. Вершина самого графика производной не является достаточным свидетельством.'),
 ('rational_intervals',['Решать рациональное неравенство методом интервалов'],'Разделить область нулями и полюсами, определить знак, учесть допустимость концов и кратности. Исходные исключения знаменателя сохраняются.'),
 ('denominator_domain',['Сохранять ограничения знаменателей'],'Выделить и сохранять нули исходных знаменателей, в том числе после сокращения. Это не весь метод интервалов.'),
 ('set_intersection',['Пересекать множества допустимых значений'],'Совместить установленные ограничения пересечением/исключением и правильно обработать границы. Не считать произвольную запись ответа доказательством ограничений.'),
 ('exponential_inequality',['Решать показательное неравенство по монотонности'],'Перейти от ограничения b^x к x, учитывая направление монотонности при b>1 и 0<b<1.'),
 ('physical_formula_substitution',['Подставлять величины в заданную формулу'],'Соотнести данные с обозначениями данной формулы, согласовать единицы и получить числовое соотношение. Вывод самой физической модели сюда не входит.'),
 ('pyramid_volume',['Вычислять объём пирамиды'],'Использовать V=Sосн h/3, где h перпендикулярна основанию; тетраэдр является частным случаем пирамиды.'),
 ('cylinder_lateral',['Вычислять площадь боковой поверхности прямого цилиндра'],'Использовать S=2πrh для прямого кругового цилиндра при обоснованных радиусе и высоте.'),
 ('optimal_bound_attainment',['Доказывать оптимальность оценкой и достижимостью'],'Получить общую границу и предъявить допустимый объект, достигающий её. Это общее доказательное действие; способ получения границы размечается отдельно.'),
]


def build():
    m=read(RUN/'manifest.json');rows=[]
    for t in m['tasks']:
        r=read(RUN/'raw'/f'{t["task_id"]}.json')
        for k in r['kc_candidates']:
            ev=[dict(step_id=s['id'],action=s['action'],result=s['result']) for s in r['steps'] if k['id'] in s['kc_ids']]
            rows.append(dict(task_id=r['task_id'],local_id=k['id'],name=k['name'],description=k['description'],evidence=ev))
    aliases={name:(cid,definition) for cid,names,definition in GROUPS for name in names}
    catalog={};links=[]
    for r in rows:
        if r['name'] in aliases:
            cid,definition=aliases[r['name']];basis='explicit_editorial_operation_group'
        else:
            cid='literal_'+digest((r['name']+'\n'+r['description']).encode())[:12]
            definition=r['description'];basis='identical_name_and_description_only'
        if cid not in catalog:
            catalog[cid]=dict(id=cid,name=r['name'],definition=definition,decision_basis=basis,members=[])
        catalog[cid]['members'].append(dict(task_id=r['task_id'],local_id=r['local_id']))
        links.append(dict(task_id=r['task_id'],local_id=r['local_id'],canonical_id=cid,
                          decision_basis=basis,source_name=r['name'],source_description=r['description'],evidence=r['evidence']))
    result=dict(version='editorial-v1',status='provisional; post-hoc primary-assistant decisions, not expert reference',
                raw_candidates=len(rows),nodes=list(catalog.values()),assignments=links,
                boundaries_not_merged=[
                    'Линейное уравнение и линейное неравенство — разные действия.',
                    'Линейная функция по двум точкам и прямая пропорциональность по одной точке — отдельные узлы; общий компонент нахождения коэффициента не объявлен эквивалентностью.',
                    'Чтение координат и восстановление формулы функции не объединены.',
                    'Взятие квадратного корня, снятие равенства корней и замена u=x² имеют разные ограничения и число прообразов.',
                    'Периодический отбор и проверка конечного набора корней не объединены.',
                    'Факторизация многочлена и решение нулевого произведения не объявлены одним полным действием.',
                    'Модель вероятности и вычисление отношения m/n — отдельно.',
                    'Ограничение области логарифма, радикала и знаменателя не слиты в один универсальный KC.'
                ])
    write(RUN/'catalog-decisions.json',result)
    print('Local KC candidates:',len(rows),'Editorial nodes:',len(catalog))


if __name__=='__main__':build()
